/* hdym_full_escape.c -- escape times of the FULL nonlinear homogeneous SU(2) Lee-Wick system
 * (nine components, hdym_full_rhs.h generated by hdym_full_derive.py), many trajectories, OpenMP.
 *
 * Integrator: Dormand-Prince 5(4), adaptive step (PI control), FSAL.  Not symplectic: the system in
 * (A, A', A'', A''') form has no separable Hamiltonian, and the Ostrogradsky energy is recorded as the
 * drift diagnostic instead.  Escape: any |A_m| or |A'_m| > R (positions and velocities of the nine
 * components), as hdym_escape_map's "any component > R" for the diagonal system.
 *
 * Per trajectory (state s[36], s[9k + m], m = 3i + a):
 *   tesc[n]      escape time, or -1 if not escaped by tmax, or -2 if the integrator failed (NaN / step underflow
 *                while the state was still within SING_R = 10 of the origin, i.e. not a runaway)
 *   status[n]    0 escaped through |A| or |A'| > R; 1 escaped "singularly": the step underflowed or the
 *                right-hand side overflowed while max |A|, |A'| was already > SING_R (a blow-up too sharp to
 *                follow to R; tesc is the time it was last resolved, within one step of the singularity);
 *                -1 not escaped; 2 integrator failure (the -2 case)
 *   sector[n]    which group held the largest |A| or |A'| at escape: 0 diagonal (m = 0,4,8),
 *                1 block 12 (m = 1,3), 2 block 13 (m = 2,6), 3 block 23 (m = 5,7); -1 if not escaped
 *   snap[n*5*NS + c*NS + j]      the full state at crossing c (NaN if it never happens)
 *   tcross[n*5 + c]              first crossing times (|w|>=1, |u_12|>=1, |u_13|>=1, |u_23|>=1, |w|>=0.1), -1 if never
 *   chk[n*nchk*6 + k*6 + g]   at checkpoint times t_k = tmax (k+1)/nchk (NaN after escape):
 *                g = 0..3 the norm sqrt(sum |A_m|^2 + |A'_m|^2) over the sector's components,
 *                g = 4 the diagonal ghost amplitude |q'' + grad V(q)| (zero on the ghost-free manifold),
 *                g = 5 the Ostrogradsky energy (drift diagnostic before escape)
 *   diag[n*4 + 0..3]  energy at t = 0, energy at the end, |G| at t = 0, |G| at the end
 * Built and called by islands/code/offdiag_escape.py.  Added 2026-10-19.
 */
#include <math.h>
#include <stdlib.h>
#ifdef _OPENMP
#include <omp.h>
#endif
#if defined(__x86_64__) || defined(_M_X64) || defined(__i386__) || defined(_M_IX86)
#include <xmmintrin.h>
#define HDYM_HAVE_MXCSR 1
#endif
#include "hdym_full_rhs.h"

/* Floating-point mode must be the same in every thread.  On Windows, numpy's MKL sets flush-to-zero /
 * denormals-are-zero on the main thread and OpenMP workers start with the default mode; the z-sector of a
 * planar background is driven only at O(delta^2), so denormals do occur, were flushed on one thread and not the
 * others, and the chaotic loiter turned that last bit into two different escape times from identical initial
 * data (20 Oct, E = 0.156: 123 cells at 2965.95, 5 cells -- one thread's share of 24 -- at 1818.84).  Every
 * thread now sets MXCSR to the x86 default 0x1F80 (round to nearest, all exceptions masked, FTZ and DAZ off),
 * which is also what Linux runs with, so results agree across threads and platforms.                        */
#define HDYM_FP_DEFAULT 0x1F80u
#ifdef _WIN32
#include <float.h>
#endif
/* returns the MXCSR the thread had (low 16 bits) and, on Windows, the x87 control word it had (high 16 bits);
 * then pins both: MXCSR = 0x1F80 and x87 precision = 53 bits, round to nearest (the only x87 user left in this
 * kernel would be the C library; the step controller no longer calls it, see ipow_fifth) */
static unsigned fp_mode_set(void)
{
    unsigned before = 0u;
#ifdef HDYM_HAVE_MXCSR
    before = _mm_getcsr() & 0xFFFFu;
    _mm_setcsr(HDYM_FP_DEFAULT);
#endif
#ifdef _WIN32
    before |= (_controlfp(0, 0) & 0xFFFFu) << 16;
    _controlfp(_PC_53, _MCW_PC);
    _controlfp(_RC_NEAR, _MCW_RC);
#endif
    return before;
}

/* x^(1/5) by Newton's method from a crude seed -- pure +,-,*,/ (and one sqrt), no C-library call, so every
 * thread and every platform computes the same step factor from the same error estimate.  err is in
 * [1e-10, ~1e3] here; 6 Newton steps from the seed sqrt(sqrt(x)) converge to rounding for that range. */
static double root5(double x)
{
    double r = sqrt(sqrt(x));
    for (int it = 0; it < 8; ++it) {
        double r4 = r * r * r * r;
        r = r - (r4 * r - x) / (5.0 * r4);
    }
    return r;
}

#define NS 36
#define SING_R 10.0

static const int SECTOR_OF_M[9] = {0, 1, 2, 1, 0, 3, 2, 3, 0};

static double sector_norm(const double *s, int g)
{
    double acc = 0.0;
    for (int m = 0; m < 9; ++m)
        if (SECTOR_OF_M[m] == g) acc += s[m] * s[m] + s[9 + m] * s[9 + m];
    return sqrt(acc);
}

static double ghost_amp(const double *s)
{
    /* diagonal ghost w = q'' + grad V(q), q_i = s[4 i] */
    double x = s[0], y = s[4], z = s[8];
    double gx = x * (y * y + z * z), gy = y * (z * z + x * x), gz = z * (x * x + y * y);
    double wx = s[18 + 0] + gx, wy = s[18 + 4] + gy, wz = s[18 + 8] + gz;
    return sqrt(wx * wx + wy * wy + wz * wz);
}

static int escaped(const double *s, double R, int *sector)
{
    double best = 0.0;
    int bm = -1;
    for (int m = 0; m < 18; ++m) {
        double v = fabs(s[m]);
        if (v > best) { best = v; bm = m % 9; }
    }
    if (best > R) { *sector = SECTOR_OF_M[bm]; return 1; }
    return 0;
}

/* Dormand-Prince 5(4) coefficients */
static const double
    a21 = 1.0 / 5.0,
    a31 = 3.0 / 40.0, a32 = 9.0 / 40.0,
    a41 = 44.0 / 45.0, a42 = -56.0 / 15.0, a43 = 32.0 / 9.0,
    a51 = 19372.0 / 6561.0, a52 = -25360.0 / 2187.0, a53 = 64448.0 / 6561.0, a54 = -212.0 / 729.0,
    a61 = 9017.0 / 3168.0, a62 = -355.0 / 33.0, a63 = 46732.0 / 5247.0, a64 = 49.0 / 176.0, a65 = -5103.0 / 18656.0,
    b1 = 35.0 / 384.0, b3 = 500.0 / 1113.0, b4 = 125.0 / 192.0, b5 = -2187.0 / 6784.0, b6 = 11.0 / 84.0,
    e1 = 71.0 / 57600.0, e3 = -71.0 / 16695.0, e4 = 71.0 / 1920.0, e5 = -17253.0 / 339200.0, e6 = 22.0 / 525.0, e7 = -1.0 / 40.0;

/* tcross[5]: first times at which the diagonal-ghost amplitude |w| reaches 1, the off-diagonal sector norms of
 * blocks 12, 13, 23 reach 1, and |w| reaches 0.1; -1 if never (added 2026-10-21, rabbit hole 4: the 50-unit
 * checkpoints cannot resolve the loiter between |w| = 1 and the blow-up).  Evaluated after every accepted step. */
/* snap[5*NS]: the full state at each of the five tcross events (rabbit hole 12: the direction of the runaway at the
 * crossings, to tell a rotating quadruplet from a directional real pair); NaN if the event never happens.  Added 2026-10-22. */
static void one_trajectory(double *s, double cj, double tmax, double R, double rtol, double atol, double hmax,
                           int nchk, double *tesc, int *sector, int *status, double *chk, double *diag, double *tcross, double *snap)
{
    double k1[NS], k2[NS], k3[NS], k4[NS], k5[NS], k6[NS], k7[NS], y[NS], ynew[NS];
    double t = 0.0, h = 1e-3, errold = 1e-4;
    double G[3], E0, E1;
    int kchk = 0;
    for (int k = 0; k < nchk * 6; ++k) chk[k] = NAN;
    for (int k = 0; k < 5; ++k) tcross[k] = -1.0;
    for (int k = 0; k < 5 * NS; ++k) snap[k] = NAN;
    hdym_full_energy_v(s, &E0, cj);
    hdym_full_gauss(s, G, cj);
    diag[0] = E0;
    diag[2] = sqrt(G[0] * G[0] + G[1] * G[1] + G[2] * G[2]);
    *tesc = -1.0;
    *sector = -1;
    *status = -1;
    for (int j = 0; j < NS; ++j) y[j] = s[j];
    hdym_full_rhs(y, k1, cj);
    long nstep = 0;
    while (t < tmax) {
        if (h > hmax) h = hmax;
        if (t + h > tmax) h = tmax - t;
        double tnext_chk = tmax * (kchk + 1) / nchk;
        if (kchk < nchk && t + h > tnext_chk) h = tnext_chk - t;
        if (h < 1e-12) {
            if (escaped(y, SING_R, sector)) { *tesc = t; *status = 1; } else { *tesc = -2.0; *status = 2; }
            break;
        }
        for (int j = 0; j < NS; ++j) ynew[j] = y[j] + h * a21 * k1[j];
        hdym_full_rhs(ynew, k2, cj);
        for (int j = 0; j < NS; ++j) ynew[j] = y[j] + h * (a31 * k1[j] + a32 * k2[j]);
        hdym_full_rhs(ynew, k3, cj);
        for (int j = 0; j < NS; ++j) ynew[j] = y[j] + h * (a41 * k1[j] + a42 * k2[j] + a43 * k3[j]);
        hdym_full_rhs(ynew, k4, cj);
        for (int j = 0; j < NS; ++j) ynew[j] = y[j] + h * (a51 * k1[j] + a52 * k2[j] + a53 * k3[j] + a54 * k4[j]);
        hdym_full_rhs(ynew, k5, cj);
        for (int j = 0; j < NS; ++j) ynew[j] = y[j] + h * (a61 * k1[j] + a62 * k2[j] + a63 * k3[j] + a64 * k4[j] + a65 * k5[j]);
        hdym_full_rhs(ynew, k6, cj);
        for (int j = 0; j < NS; ++j) ynew[j] = y[j] + h * (b1 * k1[j] + b3 * k3[j] + b4 * k4[j] + b5 * k5[j] + b6 * k6[j]);
        hdym_full_rhs(ynew, k7, cj);
        double err = 0.0;
        for (int j = 0; j < NS; ++j) {
            double ej = h * (e1 * k1[j] + e3 * k3[j] + e4 * k4[j] + e5 * k5[j] + e6 * k6[j] + e7 * k7[j]);
            double sc = atol + rtol * fmax(fabs(y[j]), fabs(ynew[j]));
            double r = ej / sc;
            err += r * r;
        }
        err = sqrt(err / NS);
        if (!(err == err)) {                                    /* NaN: overflow in the right-hand side */
            if (escaped(y, SING_R, sector)) { *tesc = t; *status = 1; } else { *tesc = -2.0; *status = 2; }
            break;
        }
        if (err <= 1.0) {
            t += h;
            for (int j = 0; j < NS; ++j) { y[j] = ynew[j]; k1[j] = k7[j]; }
            ++nstep;
            if (tcross[0] < 0.0 || tcross[4] < 0.0) {
                double ga = ghost_amp(y);
                if (tcross[4] < 0.0 && ga >= 0.1) { tcross[4] = t; for (int j = 0; j < NS; ++j) snap[4 * NS + j] = y[j]; }
                if (tcross[0] < 0.0 && ga >= 1.0) { tcross[0] = t; for (int j = 0; j < NS; ++j) snap[j] = y[j]; }
            }
            for (int g = 1; g < 4; ++g)
                if (tcross[g] < 0.0 && sector_norm(y, g) >= 1.0) { tcross[g] = t; for (int j = 0; j < NS; ++j) snap[g * NS + j] = y[j]; }
            if (kchk < nchk && fabs(t - tnext_chk) < 1e-12 * tmax) {
                for (int g = 0; g < 4; ++g) chk[kchk * 6 + g] = sector_norm(y, g);
                chk[kchk * 6 + 4] = ghost_amp(y);
                hdym_full_energy_v(y, chk + kchk * 6 + 5, cj);
                ++kchk;
            }
            if (escaped(y, R, sector)) { *tesc = t; *status = 0; break; }
            /* standard step control, fac = 0.9 err^(-1/5), computed without the C library (root5); the PI
             * variant used until 2026-10-20 called pow(), which MinGW implements in x87 code and which gave
             * thread-dependent last bits on Windows */
            double fac = 0.9 / root5(err > 1e-10 ? err : 1e-10);
            if (fac > 5.0) fac = 5.0;
            if (fac < 0.2) fac = 0.2;
            h *= fac;
            errold = err > 1e-10 ? err : 1e-10;
        } else {
            double fac = 0.9 / root5(err);
            if (fac < 0.2) fac = 0.2;
            h *= fac;
        }
    }
    hdym_full_energy_v(y, &E1, cj);
    hdym_full_gauss(y, G, cj);
    diag[1] = E1;
    diag[3] = sqrt(G[0] * G[0] + G[1] * G[1] + G[2] * G[2]);
    for (int j = 0; j < NS; ++j) s[j] = y[j];                 /* final state back to the caller */
}

void escape(double *S, int N, double cj, double tmax, double R, double rtol, double atol, double hmax,
            int nchk, double *tesc, int *sector, int *status, double *chk, double *diag, double *tcross, double *snap, int *thread_of)
{
#pragma omp parallel
    {
        fp_mode_set();
#pragma omp for schedule(dynamic, 1)
        for (int n = 0; n < N; ++n) {
#ifdef _OPENMP
            thread_of[n] = omp_get_thread_num();
#else
            thread_of[n] = 0;
#endif
            one_trajectory(S + (size_t)n * NS, cj, tmax, R, rtol, atol, hmax, nchk,
                           tesc + n, sector + n, status + n, chk + (size_t)n * nchk * 6, diag + (size_t)n * 4, tcross + (size_t)n * 5, snap + (size_t)n * 5 * NS);
        }
    }
}

/* the FP control word each thread had BEFORE the kernel set it (diagnostic: the CHECK prints min and max over
 * threads; they differed on the 20 Oct Windows run).  out[0] = min, out[1] = max, out[2] = the value set. */
void fp_mode_report(unsigned *out)
{
    unsigned mn = 0xFFFFFFFFu, mx = 0u;   /* low 16 bits MXCSR, high 16 bits x87 CW (Windows) */
#pragma omp parallel
    {
        unsigned b = fp_mode_set();
#pragma omp critical
        {
            if (b < mn) mn = b;
            if (b > mx) mx = b;
        }
    }
    out[0] = mn;
    out[1] = mx;
    out[2] = HDYM_FP_DEFAULT;
}

/* a plain integrate-to-T for the cross-check against scipy (no escape test, no checkpoints) */
void integrate_to(double *s, double cj, double T, double rtol, double atol, double hmax)
{
    double tesc, chk[6], diag[4], tcross[5], snap[5 * NS];
    int sector, status;
    fp_mode_set();
    one_trajectory(s, cj, T, 1e300, rtol, atol, hmax, 1, &tesc, &sector, &status, chk, diag, tcross, snap);
}

int omp_threads(void)
{
#ifdef _OPENMP
    return omp_get_max_threads();
#else
    return 1;
#endif
}
